// Every run of the study as a plain, serializable specification (PROTOCOL.md §4–§7), in the completed B4/B5 audit's
// RunSpec shape so its pure runner (src/b4-b5-robustness/run.ts executeSpec) and its worker threads execute them
// unchanged, and so a configuration hashes to the same specHash in both studies. The standalone books are one-book
// "pools" through the same frozen N-book engine; the pooled path re-executions are the prior audit's own VGT design
// points, regenerated by its own functions. Generation is deterministic: the same protocol gives the same list, in the
// same order, with the same keys.
import { d1Keys } from '../multi-etf-allocator/phenotypes.ts';
import { selectPhenotype } from '../phenotype/phenotypes.ts';
import {
  type BookSpec,
  type FrozenPool,
  type Grid,
  type Mode,
  type RunSpec as PriorRunSpec,
  applySample,
  dimensionsOf,
  latinHypercube,
  loadFrozenPools,
  oatPoints
} from '../b4-b5-robustness/specs.ts';
import {
  type CostScenario,
  type PoolId,
  type StandaloneId,
  base,
  controlCosts,
  costScenarios,
  jointLabel,
  jointSamples,
  jointSeeds,
  pairedPools,
  pairedSamples,
  standalonePhenotypes
} from './context.ts';

export type { BookSpec, FrozenPool, Grid, Mode } from '../b4-b5-robustness/specs.ts';

export type Family =
  | 's-base' // the standalone baselines (fixed, portfolio; full ledgers)
  | 's-control' // the standalone at the frozen controls' other costs (0, 2, 10 bps) and the symmetric dividends
  | 's-cost' // the non-base cost and execution scenarios
  | 's-oat' // one-at-a-time points (the prior audit's VGT points)
  | 's-paired' // the prior audit's per-book VGT hypercubes, run standalone
  | 's-joint' // the supplementary standalone joint eight-dimensional hypercubes
  | 'p-path'; // pooled re-executions of the prior audit's VGT design points (fixed), for lot-level paths

export const families: Family[] = ['s-base', 's-control', 's-cost', 's-oat', 's-paired', 's-joint', 'p-path'];

// The prior RunSpec with this study's own pool and family labels. Only `books`, `mode`, the costs, the rate, the stop
// fill and the dividends reach the engine (and the specHash); the labels only name records.
export type RunSpec = Omit<PriorRunSpec, 'pool' | 'family'> & { pool: StandaloneId | PoolId; family: Family };

export const asPriorSpec = (spec: RunSpec) => spec as unknown as PriorRunSpec;

const runOf = (
  partial: Omit<RunSpec, 'rate' | 'costBps' | 'stopSlippageBps' | 'stopFill' | 'dividends' | 'detail'> &
    Partial<Pick<RunSpec, 'rate' | 'costBps' | 'stopSlippageBps' | 'stopFill' | 'dividends' | 'detail'>>
): RunSpec => ({
  rate: base.rate,
  costBps: base.costBps,
  stopSlippageBps: base.stopSlippageBps,
  stopFill: base.stopFill,
  dividends: base.dividends,
  detail: false,
  ...partial
});

export const modes: Mode[] = ['fixed', 'portfolio'];

export interface Standalone {
  id: StandaloneId;
  symbol: string;
  phenotype: string;
  file: string;
  book: BookSpec;
}

// The registered phenotypes, read through the registry (read-only), as one-book pools.
export const loadStandalones = async (): Promise<Standalone[]> => {
  const loaded: Standalone[] = [];

  for (const item of standalonePhenotypes) {
    const { phenotype } = await selectPhenotype({ architecture: 'D1', symbol: item.symbol, name: item.phenotype });
    const registered = Object.fromEntries(phenotype.parameters.map((parameter) => [parameter.name, parameter.grid]));
    const grid = Object.fromEntries(d1Keys.map((key) => [key, registered[key]])) as Grid;

    for (const key of d1Keys) {
      if (!Number.isInteger(grid[key])) {
        throw new Error(`${item.file} ${item.phenotype}: ${key} has no grid value`);
      }
    }

    loaded.push({ ...item, book: { symbol: item.symbol, phenotype: item.phenotype, grid } });
  }

  return loaded;
};

export const gridEquals = (a: Grid, b: Grid) => d1Keys.every((key) => a[key] === b[key]);

// ----- the standalone runs -----

export const standaloneScenarioRun = (s: Standalone, scenario: CostScenario, mode: Mode): RunSpec =>
  runOf({
    key: `s:${s.id}:cost:${scenario.id}:${mode}`,
    family: scenario.id === 'base' ? 's-base' : 's-cost',
    pool: s.id,
    mode,
    books: [s.book],
    rate: scenario.rate,
    costBps: scenario.costBps,
    stopSlippageBps: scenario.stopSlippageBps,
    stopFill: scenario.stopFill,
    diagnostic: scenario.id !== 'base',
    // The base runs keep their full ledgers; the others keep each lot in the record (a standalone run has few).
    detail: scenario.id === 'base',
    meta: { scenario: scenario.id }
  });

export const standaloneBaseRun = (s: Standalone, mode: Mode) => standaloneScenarioRun(s, costScenarios[0]!, mode);

export const standaloneControlRuns = (s: Standalone): RunSpec[] => [
  ...controlCosts
    .filter((bps) => bps !== base.costBps)
    .flatMap((bps) =>
      modes.map((mode) =>
        runOf({
          key: `s:${s.id}:control:${bps}bps:${mode}`,
          family: 's-control',
          pool: s.id,
          mode,
          books: [s.book],
          costBps: bps,
          diagnostic: false,
          detail: false,
          meta: { controlCostBps: bps }
        })
      )
    ),
  runOf({
    key: `s:${s.id}:dividends:symmetric:portfolio`,
    family: 's-control',
    pool: s.id,
    mode: 'portfolio',
    books: [s.book],
    dividends: 'symmetric',
    diagnostic: false,
    detail: false,
    meta: { dividends: 'symmetric' }
  })
];

// The prior audit's VGT one-at-a-time points (from B4's VGT book; B5's VGT book has the same frozen vector, so the
// points are identical), applied to a standalone book with the same frozen VGT vector.
export const vgtOatPoints = (pools: Record<PoolId, FrozenPool>) =>
  oatPoints(pools.B4).filter((point) => point.symbol === 'VGT');

// The prior audit's per-book VGT hypercubes (labels 'book', <pool>, 'VGT', 1), regenerated by its own function.
export const pairedDesign = (pools: Record<PoolId, FrozenPool>, pool: PoolId) => {
  const dimensions = dimensionsOf(pools[pool].books, 'VGT');

  return { dimensions, samples: latinHypercube(dimensions, pairedSamples, 'book', pool, 'VGT', 1) };
};

// The standalone joint eight-dimensional hypercubes around a standalone book's own frozen vector.
export const jointDesign = (s: Standalone, seed: number) => {
  const dimensions = dimensionsOf([s.book], s.symbol);

  return { dimensions, samples: latinHypercube(dimensions, jointSamples, jointLabel, s.id, seed) };
};

export const allSpecs = (pools: Record<PoolId, FrozenPool>, standalones: Standalone[]) => {
  const specs: RunSpec[] = [];

  for (const s of standalones) {
    for (const scenario of costScenarios) {
      for (const mode of modes) {
        specs.push(standaloneScenarioRun(s, scenario, mode));
      }
    }

    specs.push(...standaloneControlRuns(s));

    // OAT: the prior VGT points, only when this phenotype is the pools' VGT vector (their offsets are its own).
    const isPoolVector = pairedPools.every((pool) =>
      gridEquals(pools[pool].books.find((book) => book.symbol === 'VGT')!.grid, s.book.grid)
    );

    if (isPoolVector) {
      for (const point of vgtOatPoints(pools)) {
        if (!point.feasible) {
          continue;
        }

        for (const mode of modes) {
          specs.push(
            runOf({
              key: `s:${s.id}:oat:${point.key}:${point.offset}:${mode}`,
              family: 's-oat',
              pool: s.id,
              mode,
              books: [
                { ...s.book, phenotype: `${s.book.phenotype}~diag`, grid: { ...s.book.grid, [point.key]: point.value } }
              ],
              diagnostic: true,
              detail: false,
              meta: { parameter: point.key, offset: point.offset, value: point.value }
            })
          );
        }
      }

      // The matched design: every prior per-book VGT sample, run standalone.
      for (const pool of pairedPools) {
        const { dimensions, samples } = pairedDesign(pools, pool);

        samples.forEach((values, index) => {
          for (const mode of modes) {
            specs.push(
              runOf({
                key: `s:${s.id}:paired:${pool}:${String(index).padStart(2, '0')}:${mode}`,
                family: 's-paired',
                pool: s.id,
                mode,
                books: applySample([s.book], dimensions, values),
                diagnostic: true,
                detail: false,
                meta: {
                  design: `paired-${pool}`,
                  pairedWith: `book:${pool}:VGT:${String(index).padStart(2, '0')}`,
                  sample: index
                }
              })
            );
          }
        });
      }
    }

    // The supplementary joint eight-dimensional design (two seeds of 64).
    for (const seed of jointSeeds) {
      const { dimensions, samples } = jointDesign(s, seed);

      samples.forEach((values, index) => {
        for (const mode of modes) {
          specs.push(
            runOf({
              key: `s:${s.id}:joint:s${seed}:${String(index).padStart(2, '0')}:${mode}`,
              family: 's-joint',
              pool: s.id,
              mode,
              books: applySample([s.book], dimensions, values),
              diagnostic: true,
              detail: false,
              meta: { design: `joint-s${seed}`, seed, sample: index }
            })
          );
        }
      });
    }
  }

  // Pooled re-executions (fixed): the prior audit's VGT OAT points and per-book VGT samples, with each lot kept.
  for (const pool of pairedPools) {
    const frozen = pools[pool];
    const vgt = frozen.books.find((book) => book.symbol === 'VGT')!;

    specs.push(
      runOf({
        key: `p:${pool}:base:fixed`,
        family: 'p-path',
        pool,
        mode: 'fixed',
        books: frozen.books,
        diagnostic: false,
        detail: false,
        meta: { priorKey: `cost:${pool}:base:fixed` }
      })
    );

    for (const point of oatPoints(frozen).filter((item) => item.symbol === 'VGT' && item.feasible)) {
      specs.push(
        runOf({
          key: `p:${pool}:oat:${point.key}:${point.offset}:fixed`,
          family: 'p-path',
          pool,
          mode: 'fixed',
          books: frozen.books.map((book) =>
            book.symbol === 'VGT'
              ? { ...book, phenotype: `${book.phenotype}~diag`, grid: { ...vgt.grid, [point.key]: point.value } }
              : book
          ),
          diagnostic: true,
          detail: false,
          meta: {
            priorKey: `oat:${pool}:VGT:${point.key}:${point.offset}:fixed`,
            parameter: point.key,
            offset: point.offset
          }
        })
      );
    }

    const { dimensions, samples } = pairedDesign(pools, pool);

    samples.forEach((values, index) => {
      specs.push(
        runOf({
          key: `p:${pool}:book:VGT:${String(index).padStart(2, '0')}:fixed`,
          family: 'p-path',
          pool,
          mode: 'fixed',
          books: applySample(frozen.books, dimensions, values),
          diagnostic: true,
          detail: false,
          meta: { priorKey: `book:${pool}:VGT:${String(index).padStart(2, '0')}:fixed`, sample: index }
        })
      );
    });
  }

  const keys = new Set<string>();

  for (const spec of specs) {
    if (keys.has(spec.key)) {
      throw new Error(`duplicate run key ${spec.key}`);
    }

    keys.add(spec.key);
  }

  return { specs };
};

export { loadFrozenPools };
